const redis1 = JSON.parse($json.Redis1 || '[]');
const redis2 = JSON.parse($json.Redis2 || '[]');

const combinado = Array.from(new Set([...redis1, ...redis2]));
const mensagem = combinado.join(' ');

return [{ json: { mensagem_completa: mensagem, nome: $('Dados').item.json.NomeWpp } }];

const resposta = ($json.Resposta || '').toLowerCase();

// Cenário 1: Não é nutricionista
const naoEhNutricionista = resposta.includes('profissionais de nutrição') &&
                           resposta.includes('esse contato era direcionado');

// Cenário 2: Não está atendendo
const naoEstaAtendendo = resposta.includes('profissionais que já estão ativos no atendimento');

// Cenário 3: Não quer agendar
const temDespedida = resposta.includes('te desejo muito sucesso') ||
                     resposta.includes('um abraço') ||
                     resposta.includes('um abraco') ||
                     (resposta.includes('fico a disposição') && resposta.includes('mude de ideia')) ||
                     (resposta.includes('fico à disposição') && resposta.includes('mude de ideia'));

const indicadoresEncerramento = resposta.includes('entendo completamente') ||
                                 resposta.includes('caso mude de ideia') ||
                                 resposta.includes('quando sentir que é o momento');

const naoQuerAgendar = temDespedida && indicadoresEncerramento &&
                       !resposta.includes('calendly.com');

// Cenário 4: Agendamento via Calendly (link enviado)
const agendamentoCalendly = resposta.includes('calendly.com/meet-dietsystem');

// Determinar tipo de encerramento
let tipoEncerramento = null;
if (naoEhNutricionista) tipoEncerramento = 'nao_nutricionista';
else if (naoEstaAtendendo) tipoEncerramento = 'nao_atendendo';
else if (naoQuerAgendar) tipoEncerramento = 'nao_quer_agendar';
else if (agendamentoCalendly) tipoEncerramento = 'agendamento_calendly';

return [{
  json: {
    Resposta: $json.Resposta,
    tipo_encerramento: tipoEncerramento,
    conversa_encerrada: tipoEncerramento !== null
  }
}];

// Dividir mensagem preservando quebras de linha
const resposta = $json.Resposta || '';

// Remover marcadores de sistema
let mensagem = resposta
  .replace(/\*\*AGENDAMENTO_CONFIRMADO\*\*[\s\S]*?Horario:[^\n]*\n?/gi, '')
  .replace(/AGENDAMENTO_CONFIRMADO[\s\S]*?Horario:[^\n]*\n?/gi, '')
  .trim();

// Se a mensagem for curta (menos de 500 chars), enviar como uma unica mensagem
if (mensagem.length <= 500) {
  return [{ json: { output: { messages: [mensagem] } } }];
}

// Dividir por paragrafos (blocos separados por linha em branco)
const paragrafos = mensagem.split(/\n\n+/);
const mensagens = [];
let blocoAtual = '';

for (const paragrafo of paragrafos) {
  // Se adicionar este paragrafo ultrapassar 500 chars, salvar o bloco atual
  if (blocoAtual && (blocoAtual.length + paragrafo.length + 2) > 500) {
    mensagens.push(blocoAtual.trim());
    blocoAtual = paragrafo;
  } else {
    // Adicionar ao bloco atual
    blocoAtual = blocoAtual ? blocoAtual + '\n\n' + paragrafo : paragrafo;
  }
}

// Adicionar ultimo bloco se houver
if (blocoAtual.trim()) {
  mensagens.push(blocoAtual.trim());
}

// Se ficou apenas uma mensagem muito grande, dividir por sentencas
if (mensagens.length === 1 && mensagens[0].length > 500) {
  const texto = mensagens[0];
  const partes = [];
  let parte = '';

  // Dividir por linhas primeiro para preservar formatacao
  const linhas = texto.split('\n');

  for (const linha of linhas) {
    if (parte && (parte.length + linha.length + 1) > 450) {
      partes.push(parte.trim());
      parte = linha;
    } else {
      parte = parte ? parte + '\n' + linha : linha;
    }
  }

  if (parte.trim()) {
    partes.push(parte.trim());
  }

  return [{ json: { output: { messages: partes } } }];
}

return [{ json: { output: { messages: mensagens } } }];

const messages = $json.output?.messages || [];
const telefone = $('Dados').first().json.Telefone.replace('@s.whatsapp.net', '');

const baseUrl = $('Config').first().json.config.whatsappApiUrl;
const dedicateUrl = $('Config').first().json.config.whatsappDedicateUrl;
const instance = $('Webhook Valentina').first().json.body?.instance
  || $('Webhook Valentina').first().json.instance
  || $('Config').first().json.config.whatsappInstance;

// Configuracoes de retry (existente)
const MAX_RETRIES = 5;
const INITIAL_RETRY_DELAY = 5000;
const MAX_RETRY_DELAY = 30000;

// Configuracoes de typing
const TYPING_MS_PER_CHAR = 50; // 50ms por caractere
const MIN_TYPING_TIME = 1500;  // minimo 1.5s
const MAX_TYPING_TIME = 5000;  // maximo 5s

function isConnectionError(error) {
  const errorStr = String(error?.message || error || '').toLowerCase();
  const patterns = [
    'instância não conectada', 'instance not connected',
    'not connected', 'desconectado', 'disconnected',
    'instância não encontrada', 'instance not found',
    'status code 400', 'status code 403'
  ];
  return patterns.some(p => errorStr.includes(p));
}

// Calcula tempo de digitacao baseado no tamanho da mensagem
function calculateTypingTime(messageLength) {
  const time = messageLength * TYPING_MS_PER_CHAR;
  return Math.min(Math.max(time, MIN_TYPING_TIME), MAX_TYPING_TIME);
}

// Envia status de digitando
async function sendTypingStatus(state, helpers) {
  try {
    await helpers.httpRequest({
      method: 'POST',
      url: `${baseUrl}/message/sendTypingStatus/${instance}`,
      body: { number: telefone, state },
      json: true
    });
  } catch (error) {
    // Erro de typing nao deve quebrar o fluxo
    console.log(`[Valentina] Typing status error (ignored): ${error.message}`);
  }
}

// Envia mensagem com retry (existente, mantido)
async function sendWithRetry(message, index, helpers) {
  let lastError = null;

  for (let attempt = 1; attempt <= MAX_RETRIES; attempt++) {
    try {
      const response = await helpers.httpRequest({
        method: 'POST',
        url: `${dedicateUrl}/api/message/dietsystem-main/send-text`,
        body: { phone: telefone, text: message },
        json: true
      });

      if (response.success === false || response.error) {
        const apiError = response.message || response.error || 'API returned error';
        if (isConnectionError({ message: apiError })) {
          throw new Error(apiError);
        }
        return { success: false, attempt, error: apiError };
      }

      return { success: true, attempt };

    } catch (error) {
      lastError = error;

      if (isConnectionError(error) && attempt < MAX_RETRIES) {
        const delay = Math.min(INITIAL_RETRY_DELAY * Math.pow(2, attempt - 1), MAX_RETRY_DELAY);
        console.log(`[Valentina] Msg ${index + 1}: Tentativa ${attempt}/${MAX_RETRIES} falhou. Retry em ${delay/1000}s...`);
        await new Promise(r => setTimeout(r, delay));
        continue;
      }

      return { success: false, attempt, error: error.message };
    }
  }

  return { success: false, attempt: MAX_RETRIES, error: lastError?.message || 'Max retries' };
}

// Processa todas as mensagens
const results = [];
const sentHashes = new Set();

for (let i = 0; i < messages.length; i++) {
  const msg = messages[i];
  const hash = `${telefone}:${msg.substring(0, 50)}`;

  if (sentHashes.has(hash)) {
    console.log(`[Valentina] Msg ${i + 1}: Ignorada (duplicata)`);
    continue;
  }

  // NOVO: Simula digitacao antes de enviar
  await sendTypingStatus('composing', this.helpers);
  const typingTime = calculateTypingTime(msg.length);
  console.log(`[Valentina] Msg ${i + 1}: Digitando por ${typingTime/1000}s...`);
  await new Promise(r => setTimeout(r, typingTime));

  // Envia a mensagem
  const result = await sendWithRetry(msg, i, this.helpers);

  // NOVO: Para de digitar apos enviar
  await sendTypingStatus('paused', this.helpers);

  if (result.success) {
    sentHashes.add(hash);
    results.push({ message: msg.substring(0, 50) + '...', status: 'sent', attempts: result.attempt });
  } else {
    results.push({ message: msg.substring(0, 50) + '...', status: 'failed', attempts: result.attempt, error: result.error });
  }

  // Aguarda 2 segundos entre mensagens
  if (i < messages.length - 1) {
    await new Promise(r => setTimeout(r, 2000));
  }
}

const successCount = results.filter(r => r.status === 'sent').length;
const failedCount = results.filter(r => r.status === 'failed').length;

return [{ json: { success: failedCount === 0, totalSent: successCount, totalFailed: failedCount, results } }];

// Enviar mensagem amigavel quando transcricao falhar
const telefone = $('Dados').item.json.Telefone.replace('@s.whatsapp.net', '');
const dedicateUrl = $('Config').item.json.config.whatsappDedicateUrl;

await this.helpers.httpRequest({
  method: 'POST',
  url: `${dedicateUrl}/api/message/dietsystem-main/send-text`,
  body: {
    phone: telefone,
    text: 'Desculpe, nao consegui entender seu audio. Poderia digitar sua mensagem? 🙏'
  },
  json: true
});

return [{ json: { handled: true, error: 'transcription_failed' } }];
